INSERT INTO jamb_programmes (id, jamb_name, jamb_faculty, degree_type, skills_technical, skills_transferable, skills_components, is_blend) VALUES
  ('fabf6801-11dc-5f0f-ae97-f6380e89c6af', 'Civil Law', 'Law', 'LLB', '["discuss the aim of studying psychology", "discuss and critically evaluate the schools of Psychology", "discuss the historical antecedents to modern Psychology", "explain different areas of specialisation in Psychology", "mention the methods of investigation, data collection and principles that guide scientific research; and", "discuss the relationship between psychology and other disciplines and critically evaluate the controversies in psychology.\"", "have acquired a good understanding of what Social and Political Philosophy is all about", "be familiar with the notions of society, the origin of the state, the individual in society, political obligations, leadership and", "appreciate their role as citizens and help shape their relationship with other constituents of society.\" > **NOTE — FLAG-A:** Course listed in Glossary as \"PHY 105\" but as \"PHL 105\" in table and content. See pre-extraction flags", "appreciate the various legal rules, methods, processes and reasoning", "acquire basic knowledge of the fundamental concepts of law and the various legal systems", "gain knowledge of the function of law in society; and", "appreciate the various aspects and perspectives of law.\"", "appreciate the hierarchy and categories of sources of law", "illustrate basic knowledge in the use of various legal materials and resources", "identify basic knowledge in the way and style of legal writing; and", "familiarise themselves with the ethics of the legal profession, including dress codes and modes\"", "familiarise with the ethics of the legal profession, including dress codes and modes\"", "illustrate the understanding of principles, standards, and issues in law, including formalities and precision in the use of language; the uniqueness and distinctiveness of legal terminology, rhetoric, logic, reasoning and legalism", "list the tools and skills required by law students to study and display the ability to apply them", "explain the fundamentals of English Grammar", "demonstrate ability in both reading and writing skills consisting of presentations", "organise ideas in writing of legal letters, reports, essays and examination answers; and", "distinguish between main ideas from supporting details.\"", "identify the basic features of logic as an academic discipline", "identify the main branches of logic in philosophical discourse", "describe the elementary rules of reasoning and application to logic", "recognise arguments, deduction and induction, truth and validity", "extrapolate and deploy expertise in logic to other areas of knowledge; and", "apply the knowledge and expertise acquired in logic.\"", "gain basic knowledge on the fundamental concepts and doctrines of constitutional law and constitutionalism", "tell the historical trends and constitutional developments in Nigeria and their relevance to the study of constitutional law today", "identify and analyse constitutional law issues relating to federalism, the rule of law, separation of powers, human rights, systems of government, citizenship, judicial review, amongst others", "compare the constitutional frameworks of one system and others; and", "demonstrate understanding of the implementation, interpretation and case law on provisions of the con situation.\" > **NOTE:** Item 5 reads \"con situation\" — appears to be a typographical error for \"constitution\" in the source document. Extracted verbatim", "gain basic knowledge of the fundamental concepts and doctrines of constitutional Law and constitutionalism", "appreciate the basic safeguards of every constitution", "explain the rationale behind some basic constitutional provisions such as human rights and separation of power", "appreciate the strengths and weaknesses of various types of constitutions", "tell the extent and scope of the powers of each arm of the government and whether one is superior to the other", "demonstrate an understanding of election or appointment of any government officials into office; and", "application of constitutional provisions to doctrines.\"", "understand the rationale behind some basic constitutional provisions such as human rights and separation of power", "know the extent and scope of the powers of each arm of the government and whether one is superior to the other", "tell the basic knowledge of legal concepts", "describe historical trends and developments", "appreciate sources of the Nigerian Legal System; and", "recognise the court system, the structure, hierarchy and appointment of Judicial officers in Nigeria\"", "differentiate between Common Law, Doctrines of Equity, Statutes and Customary/Islamic law", "understand the compatibility and repugnancy doctrine", "acquire knowledge and understanding of the principles of judicial construction, interpretation and the doctrine of stare decisis; and", "appreciate the requirements of becoming a legal Practitioner, a judge or a member of a judicial body\"", "be well-equipped with the basic principles governing contractual relations in Nigeria, as these principles constitute the foundation of virtually all transactions", "learn the various forms of terms expressed or implied in daily transactions; and", "be informed on the contractual liability or responsibility of a party.\"", "fully appreciate the factors rendering an agreement unenforceable", "differentiate between void, voidable and illegal contracts", "appreciate the basis under which contractual relationships terminate; and", "be introduced to ways of enforcing a contractual obligation.\"", "appreciate the sources of criminal law in Nigeria and its importance in the maintenance of law and order in the society\"", "distinguish between various crimes and their effects on the individuals and the society", "appreciate the administration of criminal justice in society", "explain the principles of punishment; and", "appreciate the application of statutes to the doctrines\"", "acquire basic knowledge and understanding of the fundamental principles of tort", "explain the concepts and history of tort law generally", "appreciate the sources of law of tort; and", "explain the contents of key legal issues in tort law.\"", "appreciate principles of liability in tort and the relationship between tort and crime", "explain scopes of trespass and nuisance", "appreciate the principles of negligence, the duty of care and strict liability; and", "comprehend defences and remedies in tort.\"", "familiarize with the legal provisions regulating selling and buying\"", "appreciate the nature and legal sources of common transactions such as the sale of goods, hire purchase and agency; and", "understand the scope of an agency relationship with the principal and third party.\"", "describe the meaning and purposes of the evidentiary rules and burden of proof", "appreciate the nature and types of evidence", "comprehend the types and roles of witnesses in legal proceedings", "appreciate the rules governing relevancy, weight and the admissibility of evidence at trial; and", "demonstrate a clear understanding of the relationship between the theoretical context of the law of evidence and its practical application at trial.\"", "understand the meaning and purposes of the evidentiary rules and burden of proof", "appreciate the importance of opinion", "know when to refer to the character of a party/witness", "describe compellability of witnesses; and", "identify the need for corroboration in evidence.\"", "understand compellability of witnesses; and", "appreciate the origins of these principles, maxims and their legal implications.\"", "appreciate the principles of trust", "comprehend the practical use of trust in the society; and", "appreciate options of administering an estate through trust.\"", "Understand the principles of trust", "comprehend the significance of the real property to economic development and legal rights involved in real/landed property.\"", "be familiar with the laws 