  ('5240d57f-d496-5679-ab3b-6cff62765203', 'df1d2654-9f7a-5942-86f0-e03a8a9b9aea', '95470556-be8e-524a-84c9-c18631726722', 'Accepts ND credit in Science Laboratory Technology or Sciences related programmes for admission by direct entry provided they have the UTME subjects at one sitting.'),
  ('e1323488-91cc-5ca1-80a5-8d8af1a85766', '9ef6e1a9-1447-55f8-9de9-14a6844e1cff', '95470556-be8e-524a-84c9-c18631726722', NULL),
