  ('81e90458-1432-5d00-9605-7aa2444d2483', 'e7c6659e-a0dc-560a-943f-4ec52c0df473', 'a3ee8b52-f45a-562a-9f13-437e335f7229', NULL),
  ('b835229b-0b0d-57d3-be78-22530d00c321', '7543ae81-5433-5429-ba08-51e6559b634f', 'a3ee8b52-f45a-562a-9f13-437e335f7229', '(li) EUI accepts Two (2) ''A'' level passes in Physics and Mathematics or Chemistry. ND/HND with Credit passes in relevant programmes from a recognized institution in addition to O'' level requirements. IJMB/JUPEB in relevant subjects.'),
  ('f344f435-34dd-5050-9d11-ff2a9846d435', '913f5f60-e942-5cf3-bf5e-17c222e3a8e7', 'a3ee8b52-f45a-562a-9f13-437e335f7229', NULL),
