  ('f9a7beea-f334-55b5-a9ec-cf3229e8b403', '4b90c4e5-c0ba-525e-9663-8fe5ce07e7c5', 'a3ee8b52-f45a-562a-9f13-437e335f7229', '(xlvii) FED-DUTSINMA accepts Two `A'' level passes in Physics and Mathematics. OND/NCE with good grades and relevant `O'' level subjects.'),
  ('7a585937-988d-5e6a-8aa3-10fa433985df', '75eaf007-a369-56a4-a009-832b8a0efd89', 'a3ee8b52-f45a-562a-9f13-437e335f7229', NULL),
