  ('6ad0c6ce-b728-5161-b2a9-73303f265c8e', 'd81f65c3-136d-5d58-9d37-713a3a995c63', '9cb03905-ba91-5a00-bdc4-ab985f5b78a2', 'UTME: require five (5) ''O'' Level credit passes in English Language, Mathematics, Chemistry, Biology and Physics.'),
  ('9ddf3e89-483c-57fc-b9e0-284a291a55ef', 'cd0c8006-ec78-5cd6-a51c-ba8884601a74', '9cb03905-ba91-5a00-bdc4-ab985f5b78a2', NULL),
